sections.css:
.radial-portal{mask-image: radial-gradient(circle, black 35%, transparent 80%); will-change: transform;}
.retina-border{box-shadow: oklch(1 0 0 / 0.15) 0px 0px 0px 0.5px inset;}
.dew-drop{position: relative; overflow: hidden; background: oklch(0.9 0.05 150 / 0.05); backdrop-filter: blur(8px); transition: transform 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275), box-shadow 0.5s, background 0.5s;}
.dew-drop:hover{transform: scale(1.03); background: oklch(0.9 0.05 150 / 0.1); box-shadow: oklch(0.75 0.25 145 / 0.5) 0px 0px 0px 0.5px inset, oklch(0.75 0.25 145 / 0.15) 0px 15px 35px;}
.subsurface-text{text-shadow: oklch(0.75 0.25 145 / 0.35) 0px 0px 45px, oklch(0.75 0.25 145 / 0.15) 0px 0px 15px; background: linear-gradient(oklch(1 0 0) 0%, oklch(0.85 0.1 150) 100%) text; -webkit-text-fill-color: transparent;}
.kinetic-sway{display: inline-block; animation: 7s ease-in-out 0s infinite normal none running sway; transform-origin: center bottom;}
.reveal-up{opacity: 0; transform: translateY(40px); transition: opacity 1.6s cubic-bezier(0.16, 1, 0.3, 1), transform 1.6s cubic-bezier(0.16, 1, 0.3, 1);}
.reveal-up.active{opacity: 1; transform: translateY(0px);}
.delay-100{transition-delay: 0.1s;}
.delay-200{transition-delay: 0.2s;}
.delay-300{transition-delay: 0.3s;}
#portal-video{will-change: transform; transform: scale(1.4);}
